sys_script_include.script:
var PropertyUpdateScriptInclude = Class.create();
PropertyUpdateScriptInclude.prototype = Object.extendsObject(AbstractAjaxProcessor, {

	   updateProperty: function(propertyName, suggestedValue) {
        var gr = new GlideRecord('sys_properties');
        if (gr.get('name', propertyName)) {
            gr.setValue('value', suggestedValue); // Update property value
            gr.update();
            return { status: 'success', message: `Property ${propertyName} updated successfully.` };
        } else {
            return { status: 'error', message: `Property ${propertyName} not found.` };
        }
    },
	 createGroup: function(groupName, description) {
        var gr = new GlideRecord('sys_user_group');

        // Check if the group already exists
        gr.addQuery('name', groupName);
        gr.query();
        if (gr.next()) {
            return { status: 'error', message: `Group '${groupName}' already exists.` };
        }

        // Create a new group
        var newGroup = new GlideRecord('sys_user_group');
        newGroup.initialize();
        newGroup.name = groupName;
        newGroup.description = description || 'Created via Script Include';
        var groupID = newGroup.insert();

        if (groupID) {
            return { status: 'success', message: `Group '${groupName}' created successfully.`, sys_id: groupID };
        } else {
            return { status: 'error', message: `Failed to create group '${groupName}'.` };
        }
    },

    type: 'PropertyUpdateScriptInclude'
});
